QUESTIONS={
'intent':{'type':'choice','instructions':POLICY['scope']+' '+POLICY['intent_rule'],'criteria':INTENTS},
'priority':{'type':'choice','instructions':POLICY['priority_rule']+' '+POLICY['critical_containment'],'criteria':{'critical':'Akute mögliche Sicherheitsgefährdung nach Testregel','urgent':'Zeitkritischer eigener Zahlungsvorgang nach Testregel, ohne akute Sicherheitsgefährdung','routine':'Keines der definierten critical-/urgent-Merkmale'}},
'next_step':{'type':'choice','instructions':POLICY['next_step_rule'],'criteria':{'security_handoff':'Sofort verifizierten Sicherheits-/Sperrservice nennen; nichts selbst ausführen','specialist_review':'Bestimmten konkreten Fall an Fachstelle zur Prüfung/Bearbeitung geben','clarify':'Zuerst gezielte nicht-geheime Sachangabe oder Priorität erfragen','guidance':'Allgemeine freigegebene Serviceinformation oder Anleitung anbieten'}}
}
rows=[]
def add(topic,n,message,intent,priority,step,reason,style='plain',question=None):
 id=f'bank_{topic}_{n:02d}'
