random.Random(20261002).shuffle(rows)
def jsonl(path,items):path.write_text(''.join(json.dumps(x,ensure_ascii=False,separators=(',',':'))+'\n' for x in items))
jsonl(DATA/'cases.jsonl',rows)
jsonl(DATA/'gold.jsonl',[{'id':r['id'],'expected':r['expected']} for r in rows])
jsonl(DATA/'metadata.jsonl',[{k:v for k,v in r.items() if k not in ['message','expected']} for r in rows])
jsonl(DATA/'requests.jsonl',[{'id':r['id'],'request':{'model':'clef-flash','state':'Synthetische Kundennachricht:\n'+r['message'],'questions':QUESTIONS}} for r in rows])
(DATA/'policy.json').write_text(json.dumps({'policy':POLICY,'questions':QUESTIONS},ensure_ascii=False,indent=2)+'\n')
